interface Pet { id: string; active: boolean }

export const activePets = (pets: Pet[]): Pet[] => {
  const result: Pet[] = []
  for (const pet of pets) {
    if (pet.active) {
      result.push(pet)
    }
  }
  return result
}

interface Pet { name: string }

export const petNames = (pets: Pet[]): string[] => {
  const names: string[] = []
  for (const pet of pets) {
    names.push(pet.name.toUpperCase())
  }
  return names
}

interface LineItem { amountCents: number }

export const invoiceTotal = (lineItems: LineItem[]): number => {
  let total = 0
  for (const lineItem of lineItems) {
    total += lineItem.amountCents
  }
  return total
}

interface Team { id: string; name: string }

export const teamsById = (teams: Team[]): Record<string, Team> => {
  const byId: Record<string, Team> = {}
  for (const team of teams) {
    byId[team.id] = team
  }
  return byId
}

interface Team { members: string[] }

export const allMembers = (teams: Team[]): string[] => {
  const members: string[] = []
  for (const team of teams) {
    for (const member of team.members) {
      members.push(member)
    }
  }
  return members
}

interface Invoice { overdue: boolean }

export const hasOverdueInvoice = (invoices: Invoice[]): boolean => {
  let found = false
  for (const invoice of invoices) {
    if (invoice.overdue) {
      found = true
    }
  }
  return found
}

interface Route { method: string; path: string }
interface Server { route: (route: Route) => void }

export const registerRoutes = (routes: Route[], server: Server): void => {
  for (const route of routes) {
    server.route(route)
  }
}

interface Reminder { to: string; body: string }
interface Mailer { send: (reminder: Reminder) => Promise<void> }

export const sendReminders = async (reminders: Reminder[], mailer: Mailer): Promise<void> => {
  for (const reminder of reminders) {
    await mailer.send(reminder)
  }
}

interface Pet { id: string }
interface Logger { info: (message: string) => void }

export const logPets = (pets: Pet[], logger: Logger): void => {
  for (const pet of pets) {
    logger.info(`Loaded pet ${pet.id}`)
  }
}

interface Pet { id: string; name: string }
interface PetRepository { save: (pet: Pet) => Promise<void> }

export const savePets = async (pets: Pet[], repository: PetRepository): Promise<void> => {
  for (const pet of pets) {
    await repository.save(pet)
  }
}

interface FileSystem { remove: (path: string) => Promise<void> }

export const cleanupImportFiles = async (paths: string[], fileSystem: FileSystem): Promise<void> => {
  for (const path of paths) {
    await fileSystem.remove(path)
  }
}

export const firstAdjacentDuplicateIndex = (weights: number[]): number => {
  let index = -1
  for (let i = 0; i < weights.length - 1; i++) {
    if (weights[i] === weights[i + 1]) {
      index = i
      break
    }
  }
  return index
}

interface Job { id: string }
interface Queue { length: number; shift: () => Job | undefined; push: (job: Job) => void }
interface JobRunner { run: (job: Job) => Job[] }

export const drainQueue = (queue: Queue, runner: JobRunner): void => {
  while (queue.length > 0) {
    const job = queue.shift()
    if (job === undefined) continue
    const followUps = runner.run(job)
    for (const followUp of followUps) {
      queue.push(followUp)
    }
  }
}

interface HttpClient { get: (url: string) => Promise<Response> }

export const fetchWithRetry = async (url: string, client: HttpClient, maxAttempts: number): Promise<Response> => {
  let attempt = 0
  let lastError: unknown
  while (attempt < maxAttempts) {
    try {
      return await client.get(url)
    } catch (error) {
      lastError = error
      attempt++
    }
  }
  throw lastError
}

interface Pet { id: string }

export const petIds = (pets: Pet[]): string[] => {
  const ids: string[] = []
  pets.forEach((pet) => {
    ids.push(pet.id)
  })
  return ids
}

export const petNames = (pets: { name: string }[]): string[] => {
  const names: string[] = []
  for (const pet of pets) {
    names.push(pet.name)
  }
  return names
}
